/*
 * A062673  Every divisor (except 1) contains the digit 6.
 * https://oeis.org/A062673
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 2140, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   check_divisors_rec, contains_digit_6_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Formula: a(n) is the n-th positive integer whose every divisor (except 1)
 * contains the digit 6.  The sequence is generated by testing successive
 * integers and storing those that satisfy the property.  The function
 * memoises found terms so that calls may arrive in any order.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/check_divisors_rec.h"
#include "../utils/contains_digit_6_seq.h"

/*--- prime sieve -------------------------------------------------------------*/
static unsigned *prime_list = NULL;    /* array of primes */
static size_t   prime_cnt   = 0;       /* number of primes stored */
static size_t   prime_cap   = 0;       /* allocated capacity */

/* initialise a prime list up to LIMIT; if a prime beyond LIMIT is needed,
 * the list is extended.  The sieve uses a compact byte array. */
static void init_primes(void)
{
    if (prime_cnt)
        return;

    const uint64_t LIMIT = 2000000U;          /* sufficient for n≈10⁴ */

    /* mark composites */
    uint8_t *is_prime = (uint8_t *)calloc((size_t)LIMIT + 1, sizeof(uint8_t));
    if (!is_prime)
        return;          /* allocation failure – caller will try again later */

    /* reserve initial prime buffer */
    prime_cap = LIMIT / 10;   /* rough capacity */
    prime_list = (unsigned *)malloc(prime_cap * sizeof(unsigned));
    if (!prime_list) {
        free(is_prime);
        return;
    }

    for (uint64_t i = 2; i <= LIMIT; ++i) {
        if (!is_prime[i]) {
            if (prime_cnt == prime_cap) {
                prime_cap *= 2;
                unsigned *tmp = (unsigned *)realloc(prime_list,
                                                    prime_cap * sizeof(unsigned));
                if (!tmp) {
                    free(is_prime);
                    free(prime_list);
                    prime_list = NULL;
                    return;
                }
                prime_list = tmp;
            }
            prime_list[prime_cnt++] = (unsigned)i;

            if (i * i <= LIMIT) {
                for (uint64_t j = i * i; j <= LIMIT; j += i)
                    is_prime[j] = 1;
            }
        }
    }
    free(is_prime);
}

/*--- divisor recursion -------------------------------------------------------*/

/*--- test whether an integer n satisfies the property ---------------------*/
static bool good_number(uint64_t n)
{
    if (n <= 1)
        return false;

    init_primes();

    /* factorisation */
    uint64_t pf[64];
    int      pe[64];
    int      pcount = 0;

    uint64_t temp = n;
    for (size_t i = 0; i < prime_cnt &&
         (uint64_t)prime_list[i] * prime_list[i] <= temp; ++i) {
        unsigned p = prime_list[i];
        if (temp % p == 0) {
            int e = 0;
            while (temp % p == 0) {
                temp /= p;
                ++e;
            }
            pf[pcount] = (uint64_t)p;
            pe[pcount] = e;
            ++pcount;
        }
    }
    if (temp > 1) {
        pf[pcount] = temp;
        pe[pcount] = 1;
        ++pcount;
    }

    /* prime factors must contain digit 6 (implied by the divisor rule) */
    for (int i = 0; i < pcount; ++i) {
        if (!contains_digit_6_seq((seq_t)pf[i]))
            return false;
    }

    /* check all divisors */
    return check_divisors_rec(0, (seq_t)1, pf, pe, pcount);
}

/*--- memoisation buffer -----------------------------------------------------*/
static seq_t *term_buf = NULL;   /* a(1), a(2), … */
static size_t term_len = 0;      /* number of stored terms   */
static size_t term_cap = 0;      /* allocated capacity       */

/*--- public function --------------------------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;   /* value undefined below offset */

    /* initialise buffer on first call */
    if (!term_buf) {
        term_cap = 64;                               /* initial capacity */
        term_buf = (seq_t *)malloc(term_cap * sizeof(seq_t));
        if (!term_buf)
            return (seq_t)0;   /* allocation failure */
        term_len = 0;
    }

    /* start searching from previous term + 1, or from 2 if none seen yet */
    uint64_t cand = 2;
    if (term_len > 0)
        cand = (uint64_t)term_buf[term_len - 1] + 1;

    /* generate terms until we have at least n of them stored */
    while (term_len < (size_t)n) {
        /* find next good number */
        while (!good_number(cand))
            ++cand;

        /* store it */
        if (term_len == term_cap) {
            term_cap *= 2;
            seq_t *tmp = (seq_t *)realloc(term_buf,
                                          term_cap * sizeof(seq_t));
            if (!tmp)
                return (seq_t)0;   /* allocation failure */
            term_buf = tmp;
        }
        term_buf[term_len++] = (seq_t)cand;
        ++cand;
    }

    return term_buf[n - 1];
}
